INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('0gax46h951woy30gaff9zd3bdathuimf', '2025-Q4', 'Dez/2025', '2025-12-30T17:27'::timestamptz, 'Nelbia Pricilla De Aguiar Dambroz', 'nelbia pricilla de aguiar dambroz', 'PHARUS', 'Gabriel Oliveira', 0.0, 'Detrator', 10.0, NULL, NULL, NULL, NULL, NULL, 'Desacreditei do método', 'Tenho clareza e estou executando com consistência', NULL, 'O valor é muito agregado para uma estratégia simples.', NULL, 'Estratégias diferenciais, que realmente faça jus a promessa da quarta via, que em 7 anos traga um fonte de renda passiva. Recentemente apresentaram a estrategia da compra por leilão, achei interessante, porém, temos pouco tempo de contrato, para usufruir melhor dessa estrategia.', 'Sim, no inicio foi nos prometido acesso as aulas, para que continuassemos no aprendizagem do motor de renda passiva, mas não foi nos apresentado nenhuma outro meio de aprendizado. 
